    purchase_order_id: string;
    receipt_id: string | null;
    kind: string;
    lines: Json;
    amount: number;
    currency: string;
    status: string;
    settlement: string | null;
    settled_amount: number | null;
    supplier_reference: string | null;
    owner_id: string;
    notes: string | null;
    created_at: Date;
